밈장면 = {'원피스': '루피가 손 내밀며 영입', '아이언맨': '슈트 안이 비었는지 두드려 보는 장면', '리얼스틸': '링 위 로봇이 사람 동작을 그대로 따라함', '어벤져스': '히어로들이 한 줄로 모임', '나야, 들기름': '정색한 얼굴로 자기 정체를 밝힘', '그런데 그것이 실제로 일어났습니다': '만화 컷 뒤에 붙는 자막', '상상도 못한 정체': '반전 공개 순간', '슬램덩크': '강백호 슛 자세, 관중석 안 선생님', '태조 왕건 궁예': '궁예가 관심법으로 신하를 노려봄', '드루와': '문 열고 도발하는 장면', '딱 대': '붙자고 손짓', '왕좌 탈환': '왕좌에 앉은 실루엣', '나노바나나 멈춰!': '손바닥 내밀어 제지', '이거 실화냐?': '눈 크게 뜨고 화면 응시', '**누가 돌아왔게** 🔥': '문 열고 압도적 성량으로 등장', '그린그린 레드레드': '비포&애프터 두 칸', '야나두': '손가락으로 가리키며 권함', '갓성비': '가격표에 후광', '아묻따': '손사래 치며 바로 결제', '떠먹여드림': '숟가락을 입에 대 줌', '딸깍': '마우스 클릭 한 번', '줬다 뺏기': '손에 쥔 걸 도로 뺏는 장면', '내 OO 돌려줘요': '울먹이며 손 내밈', '고만해, 미친놈들아!': '말리며 절규', '근데 어쩔건데?': '어깨 으쓱', '내가 고자라니': '무릎 꿇고 절규(아수라)', '오늘부터 1일': '커플이 손잡고 셀카', '꿀꺽': '큰 입이 작은 걸 삼킴', '입주': '이사 트럭이 건물로 들어감', '우리도 데려가줘요': '뒤에서 손 흔들며 따라감', '다 모여!': '한자리에 우르르', '줄줄이': '짐 싸서 줄지어 나감', '너 내 동료가 돼라': '(위와 같음)', '왔다 갑니다': '잠깐 들렀다 떠나는 뒷모습', '좌절 짤 (홍명보)': '머리를 쥐어뜯는 감독', '혼란하다 혼란해!': '웃으며 뒷걸음질 (만화체)', '더 이상의 자세한 설명은 생략한다': '자막만 있는 검은 화면', '그래도 본업은 잘해요': '딴짓하다 본업 성과 내밀기', '이 집 영업 잘하네': '식당에서 감탄', '각성 (마늘)': '흑백 인물 주변에 마늘이 떠다님', '끝판왕': '최종 보스 실루엣', '치트키': '게임 콘솔에 코드 입력', '괴물': '거대한 형체가 다가옴', '코딩 맹수': '맹수가 키보드 앞에', '감다살': '눈 감았다 뜨는 순간', '맡기고 퇴근': '가방 들고 사무실 나감', '척척 / 뚝딱': '결과물이 순식간에 완성', '열일': '땀 흘리며 일하는 캐릭터', '야 손대지마': '손 치우라고 막는 손짓', '금붕어 기억력': '금붕어 어항', '의사 가운 입은': '흰 가운을 걸친 로고 캐릭터', '**김동현(매미킴)**': '담담한 표정의 전 UFC 선수', '챗GPT 어화둥둥체': 'GPT 답변 화면, 별표 강조', '설명할 시간이 없어, 빨리 타': '**차에서 손 내밀고 뒤엔 폭발**', '스파이더맨: 브랜드 뉴 데이': '스파이더맨 슈트 (가슴 로고 교체)', '기습': '뒤에서 덮침', '크롬 시대는 끝': '간판이 떨어짐', '스파르타': '300 스타일 전사 대열', '컴활': '자격증을 들고 뿌듯한 표정', '하꼬 탈출': '작은 방에서 큰 무대로', '냉장고를 부탁해': '냉장고 열고 요리 대결', '두쫀쿠': '쿠키를 쪼개 늘어지는 단면', '**누가 돌아왔게**': '`OO에서 누가 돌아왔게~?`', '**고맙투우사**': '`고맙투우사~ 모~🐮`', '**챗GPT 어화둥둥체**': '`와… 너 정말, **핵심을 찔렀어**`', '**OO적 사고**': '`장항준적 사고` `장원영적 사고(럭키비키)`', '**그린그린 레드레드**': '`별로면 레드레드🚨 / 좋으면 그린그린💚`', '**장시간 비행**': '`장시간 비행입니다. 옆자리를 골라주세요`', '**난리자베스**': '`[감정]+자베스` (충격자베스·혜자베스)', '**갑차기스러운데**': '`갑차기스러운데 OO해도 돼?`', '**냐냐냥**': '`궁금하다면 냐냐냥!!! 입력하세요`', '**기도해 드릴게요**': '`〃`', '**동결건조**': '`〃`'}


def main(text: str, week: str, 고친것: str = "", 고친것2: str = "",
         slides: str = "") -> dict:
    memes = 밈목록
    장면표 = 밈장면
    # 늦게 고친 것부터. 이유는 06_본문검증.py 의 같은 자리를 보라.
    _글 = next((x for x in (고친것2, 고친것, text) if (x or "").strip()), text)
    표지 = json.loads(_벗기기(_글)) or {}
    h = 표지.get("headline") or []
    강조 = (표지.get("accent_text") or "").strip()
    밈이름 = (표지.get("meme") or "").strip()
    막힘, 점수 = [], []

    # **브랜드는 훅이 안 준다 — 합치기가 나중에 준다.**
    # 그래서 여기서 «합치기와 같은 규칙» 으로 직접 뽑는다: 첫 꼭지의 브랜드.
    # 이걸 안 하면 「얼굴 있는 브랜드인데 사람이 없다」 규칙이 늘 빈칸을 보고
    # 조용히 지나간다 (2026-08-21 실측).
    브랜드 = (표지.get("brand") or "").strip()
    # **`slides` 가 글자만 오는 게 아니다.** 소스(본문검증2.slides)는 `array[object]`
    # 인데 이 노드는 `string` 으로 받는다고 적어 놨다 — Dify 가 그 자리를 «맞춰» 보내
    # 주지 않고 **실제 파이썬 리스트를 그대로 넘긴다.** `(slides or "").strip()` 로
    # 재던 자리가 그래서 `AttributeError: 'list' object has no attribute 'strip'`
    # 로 죽었다(실측 2026-08-23). 리스트면 그대로 쓰고, 글자면 예전처럼 벗겨서 판다.
    if not 브랜드 and slides:
        try:
            # **`_벗기기()` 는 배열에서 «첫 {}» 만 뽑아 준다.** 마침 그게 첫 꼭지라
            # 우리가 원하는 것과 같다. 그래도 통짜 배열이 올 경우까지 받아 둔다.
            _s = slides if isinstance(slides, list) else json.loads(_벗기기(slides))
            if isinstance(_s, dict):
                _s = _s.get("slides") or _s.get("꼭지") or [_s]
            if isinstance(_s, list) and _s and isinstance(_s[0], dict):
                브랜드 = (_s[0].get("brand") or "").strip()
        except Exception:
            브랜드 = ""

    주차 = (week or "").strip()
    맞는2행 = f"{주차} AI 소식"

    # ── 되돌릴 것 ────────────────────────────────────────────
    if len(h) != 2:
        막힘.append(f"헤드라인이 {len(h)}줄이다 (2줄이어야 한다)")
    else:
        일, 이 = h[0].strip(), h[1].strip()

        # 2행은 19편 전부 예외 없이 «{N}월 {N}주차 AI 소식» 이다. 글자 하나 안 바뀐다.
        if 이 != 맞는2행:
            막힘.append(f"2행이 «{이}» 다 — «{맞는2행}» 여야 한다 (19편 전부 예외 없음)")

        # **자수로는 반려하지 않는다 (§21).** 잘리는지는 아래 폭 검사가 본다 —
        # «개발자 모여드는 한 주,» 13자가 922px 로 넉넉히 들어가는데 막고 있었다.
        # 자수는 점수표에 이미 나온다. 본문에서 정리한 것을 훅에도 맞춘다.

        # **어림이 아니라 실제 폭으로 잰다 (2026-08-20).**
        #
        # 예전엔 «순한글이면 11자까지» 라는 어림을 썼다. 순한글일 때만 맞고, 영문·숫자가
        # 섞이면 아예 안 봤다. 이제 서버와 **같은 표**로 픽셀을 잰다 — 코드 노드에는
        # 글꼴이 없어서 «글자→폭 표» 를 빌드할 때 박아 넣는다.
        for x in 넘치는_줄({"type": "표지", "headline": h}, 재는틀, 폭표들):
            if x.get("탈"):
                막힘.append(x["탈"])
                continue
            막힘.append(f"{x['자리']}이 카드 밖으로 {x['넘침']:.0f}px 나간다 — "
                       f"줄여라 (자수가 아니라 폭이 상한선이다): «{x['글']}»")

        # 강조는 «N월 N주차» 뿐이다. «AI 소식» 까지 물들이면 안 된다.
        if 강조 != 주차:
            막힘.append(f"accent_text 가 «{강조}» 다 — «{주차}» 여야 한다 "
                       f"(«AI 소식» 까지 넣으면 줄 전체가 청록이 된다)")

        # §3「두 줄 합쳐 30자 넘기기」
        # 두 줄 합계도 마찬가지 — 폭이 진짜 상한선이다.

        # §3「이모지 (표지엔 없다, 캡션에만)」
        붙은것 = [c for c in 일 + 이
                  if 0x1F300 <= ord(c) <= 0x1FAFF or 0x2600 <= ord(c) <= 0x27BF
                  or ord(c) in (0x2764, 0x2B50)]
        if 붙은것:
            막힘.append(f"헤드라인에 이모지가 있다 ({chr(32).join(붙은것)}) — §3: 표지엔 없다")

        # §3「맹물 수식어 — 19편 중 한 건도 없다」. 스킬이 «하지 말 것» 으로
        # 못 박았으니 보여주기만 하지 않고 되돌린다.
        쓴맹물 = [w for w in 맹물 if w in 일]
        if 쓴맹물:
            막힘.append(f"맹물 수식어 {쓴맹물} 를 썼다 — §3: 19편 중 한 건도 없다")

    # **밈은 반드시 고른다.** 스킬(§3)은 «19편 중 37%만 밈» 이라 했고 원본은 그렇다.
    # 그런데 밈이 없으면 서버가 `gen_prompt` 만 보고 그림을 통째로 지어내는데,
    # 그게 한눈에 «AI 가 만든 그림» 으로 보인다(실측 2026-08-20: 로고 박힌 화면 앞에서
    # 머리 쥐어뜯는 삽화가 나왔다). 밈을 주면 구도·조명을 실제 사진에서 가져오고
    # 배역만 갈아끼우기 때문에 그 티가 안 난다. **원본 분포보다 그림 품질을 택했다.**
    있는것 = {m.strip() for m in (memes or "").split(",") if m.strip()}
    if not 밈이름:
        막힘.append("밈을 안 골랐다 — 밈 없이 만든 그림은 «AI 가 만든 티» 가 난다. "
                    "밈사전에서 이 주의 판에 맞는 것을 하나 골라라")
    elif 있는것 and 밈이름 not in 있는것:
        막힘.append(f"밈 «{밈이름}» 이 밈사전에 없다 — 그림을 못 찾는다")

    프롬 = (표지.get("gen_prompt_en") or 표지.get("gen_prompt") or "").strip()
    if not 프롬:
        막힘.append("gen_prompt 가 없다 — 표지 그림을 못 만든다")
    else:
        막힘 += _프롬프트검사(프롬, 브랜드)
        점수 += _프롬프트점수(프롬)

    # §3「고른 밈의 「장면」이 gen_prompt_en 안에 실제로 들어가야 한다」
    #
    # **이름만 검사했더니 이름만 채웠다.** 밈 이름은 밈사전에 있는 것으로 골라 놓고
    # 그림은 밈과 무관한 은유로 그린 판이 나왔다(실측 2026-08-20: 금색 구슬 표지).
    #
    # 장면은 한글이고 프롬프트는 영문이라 낱말로 못 댄다. 그래서 **한글 한 줄**을
    # 따로 받는다 — `밈쓰임` 에 «그 장면을 어떻게 쓰는지» 를 적게 하고, 그것이
    # 밈사전의 장면과 실제로 겹치는지 본다. 쓰려면 장면을 읽어야 하는 구조다.
    # **밈 이름도 같이 대본다 (2026-08-21).**
    #
    # 사전의 «장면» 은 그림을 묘사한 한 줄이고(«가방 들고 사무실 나감»), LLM 은 같은
    # 뜻을 다른 말로 쓴다(«일을 몽땅 맡겨두고 퇴근하는 장면»). 그러면 겹치는 낱말이
    # 없어서 «밈을 안 썼다» 고 막힌다 — **실제로는 밈 이름을 그대로 쓰고 있었다.**
    # 밈 이름(«맡기고 퇴근»)까지 대보면 잡힌다.
    장면 = ((장면표 or {}).get(밈이름, "") + " " + 밈이름).strip()
    쓰임 = (표지.get("밈쓰임") or "").strip()
    if 밈이름 and 장면:
        if not 쓰임:
            막힘.append(f"«밈쓰임» 이 비었다 — 밈 «{밈이름}» 의 장면(«{장면}»)을 "
                        f"그림에서 어떻게 쓰는지 한 줄로 적어라")
        else:
            겹침 = _낱말(장면) & _낱말(쓰임)
            # **문턱은 «하나라도» 다 (2026-08-21).**
            #
            # 둘로 뒀더니 밈을 제대로 쓴 것을 막았다. 밈 «맡기고 퇴근» 을 «일을 몽땅
            # 맡겨두고 퇴근하는 장면» 이라고 썼는데 겹친 게 «퇴근» 하나였다 —
            # «맡기고» 와 «맡겨두고» 는 활용이 달라 앞 두 글자가 안 맞는다.
            #
            # **막으려는 것은 «이름만 대고 딴 그림을 그리는 것»** 이고, 그건 겹침이
            # 0이다(실측: 밈은 «각성(마늘)» 인데 «금색 구슬» 을 그렸다 → 0개).
            # 하나만 겹쳐도 그 밈을 보고 쓴 것이다.
            if not 겹침:
                막힘.append(f"«밈쓰임» 이 밈 «{밈이름}» 의 장면과 안 맞는다. "
                            f"장면은 «{장면}» 인데 적은 것은 «{쓰임}» 이다 "
                            f"(겹친 낱말 {sorted(겹침) or '없음'})")

    # ── 보여줄 것 ────────────────────────────────────────────
    일 = h[0].strip() if h else ""
    쓴브랜드 = [b for b in 브랜드들 if b in 일]
    갈래 = _갈래(일, 밈이름, 쓴브랜드)
    점수 = [
        f"1행 «{일}» {len(일)}자 (겨냥 {일행자수[0]}~{일행자수[1]}, 중앙 9)"
        + ("  ⚠️ 겨냥점 밖 — 폭은 통과했다" if not (일행자수[0] <= len(일) <= 일행자수[1]) else "  ✅"),
        f"두 줄 합쳐 {len(일) + len(이)}자 (겨냥 {두줄합} 이하)"
        + ("  ⚠️ 겨냥점 밖 — 폭은 통과했다" if len(일) + len(이) > 두줄합 else "  ✅"),
        f"밈: {밈이름 or '안 골랐다'}   (원본은 37%였지만 우리는 필수다 — §3)",
        f"1행 갈래(§2): {갈래}" + ("  ⚠️ 넷 중 어디인지 못 대면 다시 써라" if 갈래 == "못 댐" else "  ✅"),
        f"1행에 회사 이름: {쓴브랜드 or '없음'}"
        + ("  ⚠️ 74%는 회사 이름이 없다. 한 회사가 압도한 주에만 쓴다" if 쓴브랜드 else "  ✅"),
    ]

    return {"cover": {**표지, "headline": h, "accent_text": 강조},
            "blocked": "\n".join(막힘), "report": "\n".join(점수),
            "ok": "0" if 막힘 else "1"}
